"""M2.13 C5 in-image row (tasks/m213-spec.md C5, D8, D16, D17, D18): the image-template fixture, generated by SGLang's
own `QwenVLImageProcessor` path on GPU0, and the sidecar's bit-exact self-check against it. Pinned image only, no
network, GPU0 under `gpu0-dev.lock`:

    docker run --rm --network none \
        --gpus device=<GPU0_UUID> --user UID:GID -e HOME=/tmp -e HF_HUB_OFFLINE=1 --entrypoint python3 \
        -v REPO:/src:ro -v SGLANG_MODEL:/model:ro -v ART:/art:ro -v REPO/tests/fixtures/native:/out IMAGE \
        /src/scripts/native/gen_image_template_cases.py --model /model --artifact /art --out /out

    ... --entrypoint python3 -v REPO:/src:ro -v ART:/art:ro -v REPORTS:/report IMAGE \
        /src/scripts/native/gen_image_template_cases.py --selfcheck --artifact /art --report /report/c5.json
    ... the same with --cpu-diff (D17: the processor on the CPU against cuda:0; reported, not a gate)

SGLANG_MODEL is the directory `cere-ctl-g0` serves (`bench_backend.py` `--model-path`), ART the prepared artifact the
sidecar loads; their `preprocessor_config.json` must be byte-equal. Generation builds SGLang's tokenizer-manager
objects as `tokenizer_manager.py` does (`ServerArgs` with the control server's `--trust-remote-code`,
`get_processor_wrapper`, `get_mm_processor`), renders each case as `serving_chat.py` does (openai content format:
an image part becomes `{"type": "image"}` and an `ImageData` URL; template with `enable_thinking: false`; the
multimodal prompt is `decode(prompt_ids)`) and runs `process_mm_data_async` on it. Writes
`image_template_cases.json`:

    {"schema": "cere-image-template-cases-v1", "source": "sglang <v>, transformers <v>, torch <v>, Pillow <v>",
     "device": "cuda:0", "preprocessor_sha256": hex, "image_token_id": int,
     "hash_path": "cpu_sha256", "mm_feature_transport": "cpu", "feature_dtype": "torch.float32",
     "images": {name: {"format": "png"|"jpeg", "mode": PIL mode written, "width", "height", "seed",
                       "sha256": hex of the encoded bytes, "decoded": "pil:<mode>" | "tensor"}},
     "cases": [{"name", "messages": [{"role", "content": str | [{"type": "text", "text"} | {"type": "image",
                "image": name}]}],
                "ids": [int, ...], "images": [{"grid_thw": [t, h, w], "token_offset", "pixel_bytes",
                                               "pixel_sha256": hex of pixel_values.to(bfloat16), "pad_id"}]}]}

`ids` are SGLang's `input_ids`, `pad_id` the item's `pad_value`; generation fails unless that equals
1,000,000 + (SHA-256[:8] of the item's CPU feature bytes mod 2^30), so `hash_path` records the path SGLang took
(D16). The images are synthetic (seeded gradients plus noise) and rebuilt from `images` in memory by every mode; the
fixture holds no image bytes, only their SHA-256, which every mode checks.

`--selfcheck` starts `scripts/native/tokenizer_sidecar.py --artifact ART --feature image` and asserts, for every
case, ids, `grid_thw`, `token_offset`, `pixel_bytes`, the attachment's SHA-256 per image and `pad_id` equal the
fixture bit-exactly, `info.preprocessor_sha256` equals ART's file, no regular file is opened for write over the
run (the sidecar's `/proc/<pid>/fd` set, checked before and after) and its fds 1 and 2 are /dev/null. `--cpu-diff`
runs the artifact's processor on the decoded images on `cuda:0` and on the CPU and reports the largest difference
in 8-bit levels (one level = 2/255 after the 0.5/0.5 normalisation). Reports are scalars only.

The self-check also sends each C5n case (`C5N_CASES`: literal `<|vision_start|><|image_pad|><|vision_end|>` text,
no image part; tasks/m213-spec.md C5n, m214 N5 = b) escape, owner decision 2026-10-15) and asserts it is accepted as
text only (no `images`, no attachment), holds no image token, decodes to exactly the template's rendering and equals
N5's escaped-text encoding computed here from the artifact's tokenizer (`c5n_expected`), not from SGLang.
"""
from __future__ import annotations

import argparse
import asyncio
import base64
import hashlib
import io
import json
import os
import struct
import subprocess
import sys
import time
from pathlib import Path
from types import SimpleNamespace

SCHEMA = "cere-image-template-cases-v1"
FIXTURE = "image_template_cases.json"
DEVICE = "cuda:0"
SIDECAR = Path(__file__).resolve().parent / "tokenizer_sidecar.py"
MM_PAD_SHIFT = 1_000_000

# name: (format, mode, width, height, seed). Sizes: non-32-aligned (resize changes them), aligned (identity), below
# the processor's 65,536-pixel minimum (upscaled) and the D4 maximum of 1,024 tokens (1024 x 1024).
IMAGES = {
    "png_rgb_300x217": ("png", "RGB", 300, 217, 1),
    "png_rgba_513x385": ("png", "RGBA", 513, 385, 2),
    "png_p_trns_97x61": ("png", "P", 97, 61, 3),
    "png_l_256x256": ("png", "L", 256, 256, 4),
    "png_i16_333x250": ("png", "I;16", 333, 250, 5),
    "png_la_200x330": ("png", "LA", 200, 330, 6),
    "png_rgb_640x480": ("png", "RGB", 640, 480, 7),
    "png_rgb_1024x1024": ("png", "RGB", 1024, 1024, 8),
    "jpeg_rgb_401x299": ("jpeg", "RGB", 401, 299, 9),
    "jpeg_l_150x450": ("jpeg", "L", 150, 450, 10),
    "jpeg_rgb_512x512": ("jpeg", "RGB", 512, 512, 11),
    "png_rgba_31x33": ("png", "RGBA", 31, 33, 12),
}


def t(text: str) -> dict:
    return {"type": "text", "text": text}


def i(name: str) -> dict:
    return {"type": "image", "image": name}


CASES = [
    ("one_png_rgb", [{"role": "user", "content": [t("Describe the picture."), i("png_rgb_300x217")]}]),
    ("one_png_rgba_first", [{"role": "user", "content": [i("png_rgba_513x385"), t("What is shown?")]}]),
    ("one_png_p_trns", [{"role": "system", "content": "You are terse."},
                        {"role": "user", "content": [i("png_p_trns_97x61")]}]),
    ("one_png_l_aligned", [{"role": "user", "content": [t("Grey "), i("png_l_256x256"), t(" image.")]}]),
    ("one_png_16bit", [{"role": "user", "content": [i("png_i16_333x250"), t("sixteen bit")]}]),
    ("one_jpeg_rgb", [{"role": "user", "content": [t("A photo:"), i("jpeg_rgb_401x299")]}]),
    ("one_jpeg_l", [{"role": "user", "content": [i("jpeg_l_150x450"), t("grey jpeg \u00e9")]}]),
    ("one_max_tokens", [{"role": "user", "content": [i("png_rgb_1024x1024"), t("large")]}]),
    ("two_mixed", [{"role": "user", "content": [t("Compare "), i("png_la_200x330"), t(" with "),
                                               i("jpeg_rgb_512x512"), t(".")]}]),
    ("two_in_history", [{"role": "user", "content": [i("png_rgb_640x480"), t("first")]},
                        {"role": "assistant", "content": "A synthetic gradient."},
                        {"role": "user", "content": [t("and this one"), i("png_rgba_31x33")]}]),
    ("three_adjacent", [{"role": "user", "content": [i("png_p_trns_97x61"), i("png_l_256x256"),
                                                    i("jpeg_l_150x450"), t("three")]}]),
    ("four_images", [{"role": "system", "content": "Count the images."},
                     {"role": "user", "content": [i("png_rgb_300x217"), t("a"), i("png_i16_333x250")]},
                     {"role": "assistant", "content": "Two so far."},
                     {"role": "user", "content": [i("jpeg_rgb_401x299"), t("b"), i("png_rgba_513x385")]}]),
    ("text_only_parts", [{"role": "user", "content": [t("no image "), t("here")]}]),
]

# C5n (m213 design note; m214 N5 = b) escape, owner decision 2026-10-15): literal vision-marker text and no image
# part. Each case's user content is its only covered string; its expected ids come from N5's rule, not from SGLang.
C5N_MARKERS = "<|vision_start|><|image_pad|><|vision_end|>"
C5N_CASES = [
    ("c5n_string", [{"role": "user", "content": C5N_MARKERS + " literal"}]),
    ("c5n_text_part", [{"role": "user", "content": [t(" see " + C5N_MARKERS + " ")]}]),
]


def make_image(spec: tuple) -> tuple[bytes, str]:
    """(encoded bytes, PIL mode written) of one synthetic image: a seeded gradient plus noise."""
    import numpy as np
    from PIL import Image

    fmt, mode, width, height, seed = spec
    rng = np.random.default_rng(seed)
    y, x = np.mgrid[0:height, 0:width]
    base = (x * (200.0 / max(width - 1, 1)) + y * (55.0 / max(height - 1, 1)))[..., None]
    rgb = np.clip(base + rng.integers(-40, 41, size=(height, width, 3)) + np.array([0, 30, 60]), 0, 255)
    rgb = rgb.astype(np.uint8)
    if mode == "RGB":
        image = Image.fromarray(rgb, "RGB")
    elif mode == "RGBA":
        alpha = rng.integers(0, 256, size=(height, width, 1), dtype=np.uint8)
        image = Image.fromarray(np.concatenate([rgb, alpha], axis=2), "RGBA")
    elif mode == "P":
        image = Image.fromarray(rgb, "RGB").quantize(colors=64, method=Image.Quantize.MEDIANCUT)
    elif mode == "L":
        image = Image.fromarray(rgb[..., 1], "L")
    elif mode == "LA":
        alpha = rng.integers(0, 256, size=(height, width), dtype=np.uint8)
        image = Image.fromarray(np.stack([rgb[..., 0], alpha], axis=2), "LA")
    elif mode == "I;16":
        wide = rgb[..., 0].astype(np.uint16) * 257 + rng.integers(0, 257, size=(height, width), dtype=np.uint16)
        image = Image.fromarray(wide, "I;16")
    else:
        raise SystemExit(f"unknown mode {mode}")
    out = io.BytesIO()
    if fmt == "png":
        image.save(out, format="PNG", **({"transparency": 0} if mode == "P" else {}))
    else:
        image.save(out, format="JPEG", quality=90)
    return out.getvalue(), image.mode


def data_url(fmt: str, data: bytes) -> str:
    return f"data:image/{fmt};base64," + base64.b64encode(data).decode()


def build_images() -> dict:
    """name -> (encoded bytes, PIL mode written)."""
    return {name: make_image(spec) for name, spec in IMAGES.items()}


def api_messages(messages: list, images: dict) -> list:
    """The case's D2 request messages (data URLs) as cered forwards them to the sidecar."""
    out = []
    for m in messages:
        if isinstance(m["content"], str):
            out.append(m)
            continue
        parts = [p if p["type"] == "text" else
                 {"type": "image_url", "image_url": {"url": data_url(IMAGES[p["image"]][0], images[p["image"]][0])}}
                 for p in m["content"]]
        out.append({"role": m["role"], "content": parts})
    return out


def sha256(data) -> str:
    return hashlib.sha256(data).hexdigest()


def bf16_bytes(rows) -> memoryview:
    import torch

    return memoryview(rows.to(torch.bfloat16).contiguous().reshape(-1).view(torch.uint8).numpy())


def generate(args) -> int:
    import numpy as np  # noqa: F401 - make_image
    import PIL
    import sglang
    import torch
    import transformers
    from sglang.srt.configs.model_config import ModelConfig
    from sglang.srt.managers.multimodal_processor import get_mm_processor, import_processors
    from sglang.srt.managers.tokenizer_manager import determine_tensor_transport_mode, get_processor_wrapper
    from sglang.srt.parser.jinja_template_utils import (detect_jinja_template_content_format,
                                                        process_content_for_template_format)
    from sglang.srt.server_args import ServerArgs
    from sglang.srt.utils.common import load_image

    preprocessor = sha256((args.model / "preprocessor_config.json").read_bytes())
    if preprocessor != sha256((args.artifact / "preprocessor_config.json").read_bytes()):
        raise SystemExit("IMAGE TEMPLATE CASES FAIL: the model's and the artifact's preprocessor_config.json differ")
    server_args = ServerArgs(model_path=str(args.model), trust_remote_code=True, base_gpu_id=0)
    model_config = ModelConfig.from_server_args(server_args)
    import_processors("sglang.srt.multimodal.processors")
    processor = get_processor_wrapper(server_args)
    mm = get_mm_processor(model_config.hf_config, server_args, processor, determine_tensor_transport_mode(server_args),
                          model_config=model_config)
    tokenizer = processor.tokenizer
    template_format = detect_jinja_template_content_format(tokenizer.chat_template)
    if template_format != "openai":
        raise SystemExit(f"IMAGE TEMPLATE CASES FAIL: template content format {template_format}, expected openai")
    encode_kwargs = {"add_special_tokens": False} if tokenizer.encode("") else {}
    images = build_images()
    image_doc = {}
    for name, (data, mode) in images.items():
        fmt, _, width, height, seed = IMAGES[name]
        image_doc[name] = {"format": fmt, "mode": mode, "width": width, "height": height, "seed": seed,
                           "sha256": sha256(data)}
    cases, transports, dtypes = [], set(), set()
    for name, messages in CASES:
        image_data, rendered = [], []
        for m in api_messages(messages, images):
            rendered.append(process_content_for_template_format(m, "openai", image_data, [], [], []))
        prompt = tokenizer.apply_chat_template(rendered, tokenize=False, add_generation_prompt=True,
                                               return_dict=False, enable_thinking=False)
        prompt_ids = tokenizer.encode(prompt, **encode_kwargs)
        if not image_data:
            cases.append({"name": name, "messages": messages, "ids": prompt_ids, "images": []})
            continue
        request = SimpleNamespace(image_data=image_data, video_data=None, audio_data=None, rid=f"c5-{name}",
                                  modalities=[])
        out = asyncio.run(mm.process_mm_data_async(image_data=image_data, audio_data=None,
                                                   input_text=tokenizer.decode(prompt_ids), request_obj=request,
                                                   max_req_input_len=1 << 20))
        ids = [int(v) for v in out.input_ids]
        items = [item for item in out.mm_items if item.is_image()]
        if len(items) != len(image_data):
            raise SystemExit(f"IMAGE TEMPLATE CASES FAIL: {name}: {len(items)} items for {len(image_data)} images")
        case_images = []
        for item in sorted(items, key=lambda it: it.offsets[0][0]):
            feature = item.feature
            if not isinstance(feature, torch.Tensor):
                raise SystemExit(f"IMAGE TEMPLATE CASES FAIL: {name}: feature is {type(feature).__name__}")
            transports.add(str(feature.device))
            dtypes.add(str(feature.dtype))
            rows = feature.detach().cpu().contiguous()
            digest = hashlib.sha256(memoryview(rows.reshape(-1).view(torch.uint8).numpy())).digest()
            if item.pad_value is not None or item.hash is not None:
                raise SystemExit(f"IMAGE TEMPLATE CASES FAIL: {name}: the processor already set hash/pad_value")
            item.set_pad_value()  # the scheduler's call on the received item (`schedule_batch.py` set_pad_value)
            if item.pad_value != MM_PAD_SHIFT + int.from_bytes(digest[:8], "big") % (1 << 30):
                raise SystemExit(f"IMAGE TEMPLATE CASES FAIL: {name}: pad_value is not the CPU SHA-256 path")
            grid = [int(v) for v in item.image_grid_thw.reshape(-1).tolist()]
            start, end = item.offsets[0]
            if len(item.offsets) != 1 or end - start + 1 != grid[0] * grid[1] * grid[2] // 4:
                raise SystemExit(f"IMAGE TEMPLATE CASES FAIL: {name}: offsets {item.offsets} vs grid {grid}")
            pixels = bf16_bytes(rows)
            case_images.append({"grid_thw": grid, "token_offset": int(start), "pixel_bytes": pixels.nbytes,
                                "pixel_sha256": sha256(pixels), "pad_id": int(item.pad_value)})
        cases.append({"name": name, "messages": messages, "ids": ids, "images": case_images})
    for name, (data, _) in images.items():
        decoded, _ = load_image(data, True)
        image_doc[name]["decoded"] = "tensor" if isinstance(decoded, torch.Tensor) else f"pil:{decoded.mode}"
    if transports != {"cpu"}:
        raise SystemExit(f"IMAGE TEMPLATE CASES FAIL: features on {sorted(transports)} at hash time, expected cpu")
    doc = {"schema": SCHEMA,
           "source": f"sglang {sglang.__version__}, transformers {transformers.__version__}, torch "
                     f"{torch.__version__}, Pillow {PIL.__version__}",
           "device": DEVICE, "preprocessor_sha256": preprocessor, "image_token_id": int(model_config.image_token_id),
           "hash_path": "cpu_sha256", "mm_feature_transport": str(server_args.mm_feature_transport),
           "feature_dtype": ",".join(sorted(dtypes)), "images": image_doc, "cases": cases}
    (args.out / FIXTURE).write_text(json.dumps(doc, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
    counts = summary(doc)
    print(f"IMAGE TEMPLATE CASES WRITTEN: {counts}")
    return 0


def summary(doc: dict) -> str:
    n_images = sum(len(c["images"]) for c in doc["cases"])
    return f"{len(doc['cases'])} cases, {n_images} images, {len(doc['images'])} distinct"


def load_fixture(path: Path, images: dict) -> dict:
    doc = json.loads(path.read_text(encoding="utf-8"))
    if doc.get("schema") != SCHEMA:
        raise SystemExit(f"IMAGE TEMPLATE SELFCHECK FAIL: {path} is not {SCHEMA}")
    for name, entry in doc["images"].items():
        if sha256(images[name][0]) != entry["sha256"]:
            raise SystemExit(f"IMAGE TEMPLATE SELFCHECK FAIL: image {name} does not rebuild to its fixture bytes")
    return doc


class Sidecar:
    def __init__(self, artifact: Path):
        self.proc = subprocess.Popen([sys.executable, str(SIDECAR), "--artifact", str(artifact), "--feature", "image"],
                                     stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    def send(self, obj: dict) -> None:
        data = json.dumps(obj, ensure_ascii=False).encode()
        self.proc.stdin.write(struct.pack("<I", len(data)) + data)
        self.proc.stdin.flush()

    def frame(self) -> bytes:
        (n,) = struct.unpack("<I", self.read(4))
        return self.read(n)

    def read(self, n: int) -> bytes:
        data = self.proc.stdout.read(n)
        if len(data) != n:
            err = self.proc.stderr.read().decode(errors="replace").strip()
            raise SystemExit(f"IMAGE TEMPLATE SELFCHECK FAIL: the sidecar exited ({err})")
        return data

    def fds(self) -> dict:
        out = {}
        base = Path(f"/proc/{self.proc.pid}/fd")
        for fd in base.iterdir():
            try:
                target = os.readlink(fd)
                flags = int((Path(f"/proc/{self.proc.pid}/fdinfo") / fd.name).read_text().split("flags:")[1].split()[0],
                            8)
            except (OSError, IndexError, ValueError):
                continue
            out[int(fd.name)] = (target, flags & 0o3)
        return out

    def close(self) -> int:
        self.proc.stdin.close()
        return self.proc.wait(timeout=120)


def written_files(fds: dict) -> set:
    """Regular files open for writing (O_WRONLY or O_RDWR); devices, pipes, sockets and anon inodes excluded."""
    return {target for target, mode in fds.values()
            if mode in (1, 2) and target.startswith("/") and not target.startswith(("/dev/", "/proc/"))}


def c5n_expected(tok, plain, kwargs: dict, messages: list) -> tuple[str, list]:
    """(rendering, ids) by N5's rule for a request whose only covered string is its user content: the rendering
    outside the content's core (the content without its leading and trailing whitespace) encoded as today, the core
    alone by the tokenizer's pipeline without its added tokens (`plain`)."""
    content = messages[-1]["content"]
    core = (content if isinstance(content, str) else "".join(p["text"] for p in content)).strip()
    rendered = tok.apply_chat_template(messages, tokenize=False, add_generation_prompt=True, enable_thinking=False)
    start = rendered.index(core)
    ids = tok.encode(rendered[:start], **kwargs) + plain.encode(core, add_special_tokens=False).ids
    return rendered, ids + tok.encode(rendered[start + len(core):], **kwargs)


def c5n_selfcheck(sidecar: "Sidecar", artifact: Path, image_token_id: int, failures: list) -> int:
    """Each C5n case is accepted as text only (no `images`, no attachment), holds no image token, decodes to exactly
    the template's rendering and equals N5's escaped-text encoding. Returns the case count."""
    import tokenizers
    import transformers
    tok = transformers.AutoTokenizer.from_pretrained(str(artifact), local_files_only=True, trust_remote_code=False,
                                                     clean_up_tokenization_spaces=False, use_fast=True)
    spec = json.loads(tok.backend_tokenizer.to_str())
    spec.update(added_tokens=[], truncation=None, padding=None)
    plain = tokenizers.Tokenizer.from_str(json.dumps(spec))
    kwargs = {"add_special_tokens": False} if tok.encode("") else {}
    for name, messages in C5N_CASES:
        sidecar.send({"op": "encode_chat", "messages": messages})
        reply = json.loads(sidecar.frame())
        if not reply.get("ok"):
            failures.append(f"{name}: error {reply.get('error', {}).get('type')}")
            continue
        if "images" in reply or "attachment_bytes" in reply:
            failures.append(f"{name}: literal marker text made an image span")
            continue
        rendered, want = c5n_expected(tok, plain, kwargs, messages)
        if image_token_id in reply["ids"]:
            failures.append(f"{name}: an image token from literal text")
        if tok.decode(reply["ids"], skip_special_tokens=False) != rendered:
            failures.append(f"{name}: ids do not decode to the rendering")
        if reply["ids"] != want:
            failures.append(f"{name}: ids differ from the escaped-text encoding")
    return len(C5N_CASES)


def selfcheck(args) -> int:
    images = build_images()
    doc = load_fixture(args.fixture, images)
    started = time.monotonic()
    sidecar = Sidecar(args.artifact)
    sidecar.send({"op": "info"})
    info = json.loads(sidecar.frame())
    startup_s = time.monotonic() - started
    failures = []
    preprocessor = sha256((args.artifact / "preprocessor_config.json").read_bytes())
    if (info.get("features") != ["image", "message_boundary", "thinking"]
            or info.get("preprocessor_sha256") != preprocessor):
        failures.append("info: features/preprocessor_sha256")
    if preprocessor != doc["preprocessor_sha256"]:
        failures.append("fixture preprocessor_sha256 differs from the artifact")
    fds_before = sidecar.fds()
    images_checked = ids_checked = 0
    for case in doc["cases"]:
        sidecar.send({"op": "encode_chat", "messages": api_messages(case["messages"], images)})
        reply = json.loads(sidecar.frame())
        if not reply.get("ok"):
            failures.append(f"{case['name']}: error {reply.get('error', {}).get('type')}")
            continue
        ids_checked += len(reply["ids"])
        if reply["ids"] != case["ids"]:
            first = next((k for k, (a, b) in enumerate(zip(reply["ids"], case["ids"])) if a != b),
                         min(len(reply["ids"]), len(case["ids"])))
            failures.append(f"{case['name']}: ids differ at {first} (len {len(reply['ids'])} vs {len(case['ids'])})")
        if not case["images"]:
            if "images" in reply or "attachment_bytes" in reply:
                failures.append(f"{case['name']}: a text-only reply carries images")
            continue
        attachment = sidecar.frame()
        if reply.get("attachment_bytes") != len(attachment):
            failures.append(f"{case['name']}: attachment_bytes {reply.get('attachment_bytes')} vs {len(attachment)}")
        got = reply.get("images", [])
        if len(got) != len(case["images"]):
            failures.append(f"{case['name']}: {len(got)} images vs {len(case['images'])}")
            continue
        start = 0
        for k, (mine, want) in enumerate(zip(got, case["images"])):
            chunk = attachment[start:start + mine["pixel_bytes"]]
            start += mine["pixel_bytes"]
            for key in ("grid_thw", "token_offset", "pixel_bytes", "pad_id"):
                if mine[key] != want[key]:
                    failures.append(f"{case['name']} image {k}: {key} {mine[key]} vs {want[key]}")
            if sha256(chunk) != want["pixel_sha256"]:
                failures.append(f"{case['name']} image {k}: pixel_values SHA-256 differs")
            images_checked += 1
    c5n = c5n_selfcheck(sidecar, args.artifact, doc["image_token_id"], failures)
    fds_after = sidecar.fds()
    new_written = written_files(fds_after) - written_files(fds_before)
    if written_files(fds_after) or new_written:
        failures.append(f"{len(written_files(fds_after))} regular files open for write")
    devnull = all(fds_after.get(fd, ("", 0))[0] == "/dev/null" for fd in (1, 2))
    if not devnull:
        failures.append("fds 1/2 are not /dev/null")
    rc = sidecar.close()
    if rc != 0:
        failures.append(f"sidecar exit {rc}")
    report = {"row": "C5", "mode": "selfcheck", "outcome": "pass" if not failures else "fail",
              "cases": len(doc["cases"]), "c5n_cases": c5n, "images_checked": images_checked,
              "ids_checked": ids_checked,
              "failures": len(failures), "fixture_sha256": sha256(args.fixture.read_bytes()),
              "preprocessor_sha256": preprocessor, "hash_path": doc["hash_path"], "device": doc["device"],
              "fds_written_regular": len(written_files(fds_after)), "fds_1_2_devnull": devnull,
              "sidecar_startup_s": round(startup_s, 3), "source": doc["source"]}
    write_report(args, report)
    for f in failures[:40]:
        print("  " + f)
    word = "PASS" if not failures else "FAIL"
    print(f"IMAGE TEMPLATE SELFCHECK {word}: {summary(doc)}, {c5n} C5n cases, {images_checked} images and "
          f"{ids_checked} ids checked, {len(failures)} failures")
    return 0 if not failures else 1


def cpu_diff(args) -> int:
    import torch
    import transformers
    from sglang.srt.utils.common import load_image

    images = build_images()
    processor = transformers.AutoImageProcessor.from_pretrained(str(args.artifact), local_files_only=True)
    level = 2.0 / 255.0
    worst = 0.0
    differing = bf16_differing = 0
    per_image = []
    for name, (data, _) in images.items():
        decoded, _ = load_image(data, True)
        if not isinstance(decoded, torch.Tensor):
            decoded = decoded.convert("RGB") if decoded.mode != "RGB" else decoded
        gpu = processor(images=[decoded], return_tensors="pt", device=DEVICE)
        cpu_input = decoded.cpu() if isinstance(decoded, torch.Tensor) else decoded
        cpu = processor(images=[cpu_input], return_tensors="pt", device="cpu")
        a = gpu["pixel_values"].to("cpu").float()
        b = cpu["pixel_values"].to("cpu").float()
        if a.shape != b.shape or gpu["image_grid_thw"].tolist() != cpu["image_grid_thw"].tolist():
            raise SystemExit(f"IMAGE CPU DIFF FAIL: {name}: shapes differ")
        diff = float((a - b).abs().max()) / level
        worst = max(worst, diff)
        differing += int(diff > 0)
        bf16_differing += int(not torch.equal(a.to(torch.bfloat16), b.to(torch.bfloat16)))
        per_image.append(round(diff, 4))
    report = {"row": "C5", "mode": "cpu_diff", "gate": False, "images": len(images),
              "max_level_diff": round(worst, 4), "images_differing_f32": differing,
              "images_differing_bf16": bf16_differing, "per_image_max_level_diff": per_image}
    write_report(args, report)
    print(f"IMAGE CPU DIFF (not a gate): {len(images)} images, max {worst:.4f} levels, {differing} differ in f32, "
          f"{bf16_differing} in bf16")
    return 0


def write_report(args, report: dict) -> None:
    if args.report is not None:
        args.report.write_text(json.dumps(report, indent=1) + "\n", encoding="utf-8")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--model", type=Path, help="the directory cere-ctl-g0 serves (generation)")
    parser.add_argument("--artifact", type=Path, required=True, help="the prepared artifact the sidecar loads")
    parser.add_argument("--out", type=Path, help="fixture directory (generation)")
    parser.add_argument("--selfcheck", action="store_true", help="the sidecar against the fixture (C5 in-image)")
    parser.add_argument("--cpu-diff", action="store_true", help="processor on the CPU vs cuda:0 (D17, not a gate)")
    parser.add_argument("--fixture", type=Path, default=SIDECAR.parents[2] / "tests/fixtures/native" / FIXTURE)
    parser.add_argument("--report", type=Path, help="scalar JSON report")
    args = parser.parse_args(argv)
    if args.selfcheck:
        return selfcheck(args)
    if args.cpu_diff:
        return cpu_diff(args)
    if args.model is None or args.out is None:
        parser.error("generation needs --model and --out")
    return generate(args)


if __name__ == "__main__":
    sys.exit(main())
